import json, os
OUT = '/workspace/kalliope/design/ricerca/osservazioni'

def o(car, amb, stato, ev=None, valore=None, descr=None, nm=None, motivo=None):
    r = {'caratteristica': car, 'ambito': amb, 'stato': stato}
    if valore is not None: r['valore'] = valore
    if nm: r['non_misurati'] = nm
    if descr: r['descrizione'] = descr
    if ev: r['evidenze'] = ev
    if motivo: r['motivo'] = motivo
    return r

def no(car, amb, motivo): return o(car, amb, 'non_osservato', motivo=motivo)

