for ID, obs in (('R01', R01), ('R02', R02), ('R03', R03)):
    m = META[ID]
    doc = {'riferimenti': [{'id': ID, **m, 'osservazioni': obs}]}
    with open(os.path.join(OUT, ID + '.json'), 'w', encoding='utf8') as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    print(ID, len(obs), 'osservazioni')
